export const obligationsAndContracts_723_958: Record<string, string> = {
  "723": "إجارة الخدمة[187] أو العمل عقد يلتزم بمقتضاه أحد طرفيه بأن يقدم للآخر خدماته الشخصية لأجل محدد، أو من أجل أداء عمل معين، في نظير أجر يلتزم هذا الآخر بدفعه له.\n(ظهير 18 ديسمبر 1947) وإذا كان العقد ثابتا بالكتابة أعفي من رسوم التمبر والتسجيل[188].\nوإجارة الصنعة عقد بمقتضاه يلتزم أحد الطرفين بصنع شيء معين في مقابل أجر يلتزم الطرف الآخر بدفعه له.\nوفي الحالتين يتم العقد بتراضي الطرفين[189].",
  "724": "يعتبر القانون بمثابة إجارة الصنعة، العقد الذي يلتزم بمقتضاه الأشخاص الذين يباشرون المهن والفنون الحرة بتقديم خدماتهم لزبنائهم، وكذلك الشأن بالنسبة إلى الأساتذة وأرباب العلوم والفنون والحرف.",
  "725": "إجارة الصنعة وإجارة الخدمة لا تقعان صحيحتين إلا إذا كان عاقداهما متمتعين بأهلية الالتزام. وتجب مساعدة المحجور عليه والقاصر ممن له الولاية عليهما[190].",
  "726": "[الفصل 726 محذوف]",
  "727": "لا يسوغ للشخص أن يؤجر خدماته إلا إلى أجل محدد، أو لأداء عمل معين، أو لتنفيذه، وإلا وقع العقد باطلا بطلانا مطلقا[192].",
  "728": "يبطل كل اتفاق يلتزم بمقتضاه شخص بتقديم خدماته طوال حياته، أو لمدة تبلغ من الطول حدا بحيث يظل ملتزما حتى موته.",
  "729": "يبطل كل اتفاق يكون موضوعه:\nأ - تعليم أو أداء أعمال السحر والشعوذة، أو القيام بأعمال مخالفة للقانون، أو للأخلاق الحميدة، أو للنظام العام؛\nب - القيام بأعمال مستحيلة ماديا.",
  "730": "يلزم أن يكون الأجر محددا أو قابلا للتحديد[193]. ويسوغ أن يكون الأجر حصة محددة من المكاسب أو الحاصلات، كما يسوغ أن يكون بمقدار نسبي على الأعمال التي يجريها المؤجر على يد الأجير[194].",
  "731": "إلا أنه لا يسوغ للمحامين والوكلاء وغيرهم ممن يقومون بنوازل الخصام أن يعقدوا، بأنفسهم أو بواسطة غيرهم، مع زبنائهم أي اتفاق على القضايا والحقوق والدعاوى المتنازع عليها أو على الأشياء التي تتعلق بالأشغال المناطة بهم بصفاتهم تلك. وكل اتفاق من هذا النوع يقع باطلا بقوة القانون والخسارة إن وقعت تلزم المتسبب فيها.",
  "732": "يعتبر الاتفاق على الأجر أو الراتب موجودا ولو لم يصرح به:\nأولا: إذا كانت الخدمات أو الصنعة مما لم تجر العادة على أدائه مجانا.\nثانيا: إذا كان الشخص بأدائه الخدمات أو الصنعة قد باشر مهنته.\nثالثا: إذا تعلق الأمر بصفقة تجارية أو بعمل أداه التاجر في مباشرة تجارته.",
  "733": "إذا لم يحدد الاتفاق أجر الخدمات أو الصنعة، تولت المحكمة تحديده وفق العرف[195]. وإذا وجدت تعريفة أو أسعار محددة، افترض في المتعاقدين أنهما ارتضياها[196].",
  "734": "على رب العمل أو السيد أن يدفع الأجر وفق ما هو مذكور، في العقد أو مقرر بمقتضى العرف[197] المحلي[198]. فإذا لم يحدد الاتفاق ولا العرف[199] طريقة دفع الأجرة، فإنه لا يكون واجب الدفع إلا بعد أداء ما يقضي به العقد من الخدمات أو الصنع. والخدام الذين يلتزمون بالخدمة لمدة معينة، يستحقون أجورهم مياومة ما لم يقض الاتفاق أو العرف[200] بخلافه.",
  "735": "من التزم بتنفيذ صنع أو بأداء خدمات معينة يستحق الأجر الذي وعد به بتمامه، إذا لم يتمكن من تقديم خدماته أو إتمام الصنع الموعود به لسبب راجع إلى شخص رب العمل، بشرط أن يكون قد وضع نفسه تحت تصرفه ولم تؤجر خدماته لشخص آخر[201].\nومع ذلك، يحق للمحكمة أن تخفض الأجر المشترط بحسب مقتضيات الظروف[202].",
  "736": "لا يجوز لأجير الخدمة أو الصنعة أن يعهد بتنفيذ مهمته إلى شخص آخر، إذا ظهر من طبيعة الخدمة أو الصنع أو من اتفاق الطرفين أن لرب العمل مصلحة في أن يؤدي الأجير بنفسه التزامه[203].",
  "737": "من يلتزم بإنجاز صنع أو بأداء خدمة يسأل، ليس فقط عن فعله ولكن أيضا عن إهماله ورعونته وعدم مهارته[204].\nوكل شرط مخالف لذلك يكون عديم الأثر.",
  "738": "وهو يسأل أيضا عن النتائج المترتبة عن عدم مراعاة التعليمات التي تلقاها إن كانت صريحة، ولم يكن له مبرر خطير يدعوه لمخالفتها، وإذا وجد هذا المبرر لزمه أن يخطر به رب العمل وأن ينتظر تعليماته، ما لم يكن في التأخير ما تخشى عاقبته.",
  "739": "يسأل أجير العمل عن فعل وعن خطإ الأشخاص الذين يحلهم محله في أدائه أو يستخدمهم أو يستعين بهم فيه في نفس الحدود التي يسأل فيها عن فعل أو خطأ نفسه.\nإلا أنه إذا اضطر، بسبب طبيعة الخدمات أو العمل موضوع العقد إلى الاستعانة بأشخاص آخرين، فإنه لا يتحمل بأي مسؤولية، إذا أثبت:\nأولا: أنه بذل في اختيار هؤلاء الأشخاص والرقابة عليهم كل ما يلزم من العناية؛\nثانيا: أنه فعل من جانبه كل ما يلزم لمنع الضرر أو لدرء عواقبه.",
  "740": "أجير الخدمة وأجير الصنعة اللذان لا يقدمان إلا العمل يلتزمان بالمحافظة على الأشياء التي تسلم لهما لأداء ما يكلفان به من الخدمة أو الصنع. ويجب عليهما رد هذه الأشياء بعد أداء شغلهما. ويضمنان هلاكها أو تعيبها الحاصل بخطإهما[205].\nوإذا كانت الأشياء التي تسلماها غير لازمة لأداء شغلهما، فإنهما لا يسألان عنها إلا باعتبارها مجرد وديعة.",
  "741": "وهما لا يسألان عن العيب والهلاك الناتج من الحادث الفجائي أو القوة القاهرة اللذين لم يتسببا عن فعلهما أو عن خطإهما[206]، مع استثناء حالة مطلهما في رد الأشياء التي عهد إليهما بها.\nهلاك الشيء الحاصل نتيجة العيوب التي تلحقه أو نتيجة شدة قابليته للكسر يقع بمثابة الحادث الفجائي إذا لم يكن ثمة خطأ من الأجير.\nإثبات القوة القاهرة يقع على عاتق أجير العمل.",
  "742": "سرقة أو اختلاس الأشياء التي يجب على أجير الخدمة أو الصنعة ردها للسيد أو لرب العمل لا يعتبران بمثابة القوة القاهرة المبرئة لذمته، ما لم يثبت أنه اتخذ كل ما يلزم من الحيطة لدرء هذا الخطر.",
  "743": "أصحاب النُّزُل والفنادق، ومن يكرون الدور أو الغرف المفروشة وملاك الحمامات والمقاهي والمطاعم والملاهي العامة يسألون عن هلاك وتعيب وسرقة الأشياء والأمتعة التي يأتي بها النزلاء والرواد في محلاتهم، سواء أكان ذلك ناشئا بفعل خدامهم ومأموريهم، أو بفعل الرواد الآخرين لمحلاتهم.\nويبطل كل شرط من شأنه أن يبعد أو يقيد مسؤولية الأشخاص السابقين على نحو ما هو مقرر في القانون.",
  "744": "لا يكون الأشخاص المذكورون في الفصل السابق مسؤولين إذا أثبتوا أن الهلاك أو التعيب يرجع في سببه إلى:\nأولا: فعل مالك الأمتعة أو خدامه أو الأشخاص الذين معه أو إهمالهم الجسيم؛\nثانيا: طبيعة أو عيب الأشياء التي هلكت أو تعيبت؛\nثالثا: قوة قاهرة أو حادث فجائي لا يعزى إلى خطإهم أو إلى خطأ ممثليهم أو مأموريهم أو خدامهم. وإثبات الوقائع السابقة يقع على عاتقهم. وهم لا يسألون عن كل ما يلحق الوثائق والنقود والأوراق المالية والأشياء الثمينة التي لم تسلم لهم أو لمأموريهم.",
  "745": "إجارة الصنعة وإجارة الخدمة تنقضيان:\nأولا: بانتهاء الأجل المقرر أو بأداء الخدمة[207] أو الصنع الذي كان محلا للعقد؛\nثانيا: بالفسخ المحكوم به من القاضي في الحالات التي يحددها القانون[208]؛\nثالثا: باستحالة التنفيذ الناشئة إما بسبب حادث فجائي أو قوة قاهرة وإما بسبب وفاة مؤجر الصنعة أو الخدمة، مع مراعاة ما يقضي به القانون من استثناءات بالنسبة إلى الحالة الأخيرة، ولا تنفسخ الإجارتان بموت السيد أو رب العمل[209].",
  "746": "تنظم إجارة الخدمة بمقتضى الأحكام العامة الواردة في الفصل 723 وما بعده وبمقتضى الأحكام الآتية:",
  "747": "إذا كان الأجير يعيش في منزل مخدومه، ثم مرض أو أصيب في حادثة من غير أن يكون ذلك راجعا إلى خطإه، وجب على المخدوم أن يقدم له وعلى نفقته ولمدة عشرين يوما، ما يلزم لمؤونته ولعلاجه.\nويسوغ للمخدوم أن يقدم للأجير العلاج خارج منزله، في مؤسسة عامة مخصصة لذلك، وأن يخصم ما ينفقه في هذا السبيل مما يستحقه الأجير من أجر.",
  "748": "يعفى المخدوم من الالتزام المقرر في الفصل السابق إذا كان في مقدور الأجير الحصول على ما يلزمه من مؤونة وعلاج، من جمعيات الإغاثة التعاونية التي يكون عضوا فيها، أو من شركات التأمين التي يكون أمن عندها أو من الإسعاف العمومي.",
  "749": "المعلم أو المخدوم، وعلى العموم كل رب عمل، يلتزم:\nأولا - بأن يعمل على أن تكون الغرف، ومحلات الشغل، وعلى العموم كل الأماكن التي يقدمها لعماله وخدمه ومستخدميه مستوفية كل الشروط اللازمة لعدم إلحاق الضرر بصحتهم ولتأمينهم من كل خطر، كما أنه يلتزم بصيانتها لتبقى على نفس هذه الحالة طوال مدة العقد[215]؛\nثانيا - بأن يعمل على أن تكون الأجهزة والآلات والأدوات وعلى العموم كل الأشياء التي يقدمها، والتي يلزم بواسطتها أداء الشغل في حالة من شأنها أن تقي من يستخدمهم من كل خطر يهدد حياتهم أو صحتهم في الحدود التي تقتضيها طبيعة الخدمات التي يؤدونها، كما أنه يلتزم بصيانتها لتبقى على نفس هذه الحالة طوال مدة العقد[216]؛\nثالثا - بأن يتخذ كل ما يلزم من الإجراءات الوقائية لكي يؤمن لعماله وخدمه ومستخدميه حياتهم وصحتهم في أدائهم الأعمال التي يباشرونها تحت توجيهه أو لحسابه[217].\nويسأل المخدوم عن كل مخالفة لأحكام هذا الفصل وفقا للقواعد المقررة للجرائم وأشباه الجرائم[218].",
  "750": "ويسأل المخدوم أيضا عن الحوادث والكوارث التي يقع ضحيتها الأجير الذي يعمل معه، حالة كونه يؤدي المهمة التي عهد إليه بها، إذا كان سبب الحادثة أو الكارثة راجعا إلى مخالفة أو عدم مراعاة رب العمل الضوابط الخاصة المتعلقة بمباشرة صناعته أو فنه[219].",
  "751": "كل الاشتراطات أو الاتفاقات التي تستهدف تخفيف أو إبعاد المسؤولية المقررة بمقتضى الفصلين 749 و750 على عاتق المخدومين أو أرباب الأعمال تقع عديمة الأثر.",
  "752": "يسوغ إنقاص التعويض، إذا ثبت أن الحادثة التي كان الأجير ضحيتها قد تسببت عن عدم حيطته أو عن خطإه وتزول مسؤولية المخدوم كلية، ولا يمنح أي تعويض للأجير، إذا كان سبب الحادثة راجعا إلى سكره أو إلى خطإه الجسيم[220].",
  "753": "( ظهير 6 يوليوز 1954)\nتنقضي إجارة الخدمة بانقضاء المدة التي حددها الطرفان[221].\nإذا ارتضى المتعاقدان صراحة عند إبرام عقد محدد المدة، إمكانية تجديده وحددا عدد مرات التجديد، لم يسغ لهما أن يحددا لكل من هذه المرات مدة تتجاوز المدة التي حددت للعقد ومن غير أن تزيد في أي حالة على سنة. والعقد الذي يبرم لمدة محددة يمكن أن يمتد بالتجديد الضمني إلى ما بعد أجله المشروط. وفي هذه الحالة يصبح غير محدد المدة[222].",
  "754": "(ظهير 26 شتنبر 1938) إذا لم تحدد مدة العقد، وكان ذلك راجعا إلى إرادة المتعاقدين أو إلى طبيعة العمل اللازم أداؤه، فإن العقد يقع قابلا للإبطال، ويسوغ لأي من المتعاقدين أن يتخلص منه بإعطائه تنبيها بذلك للطرف الآخر في المواعيد التي يقررها العرف[223] المحلي أو الاتفاق. ويستحق الأجر بنسبة الخدمات المؤداة، وعلى حسب ما هو مستحق للأعمال المماثلة[224].\nيسوغ في إجارة الخدمة، بمقتضى الاتفاقات الجماعية[225]، مخالفة المواعيد المحددة بمقتضى العرف[226].\nكل شرط يحدد في عقد فردي أو في ضابط مصنع ميعادا للتنبيه أدنى مما هو مقرر بمقتضى العرف[227] أو بمقتضى الاتفاقات الجماعية يقع باطلا بقوة القانون[228].\nفسخ العقد بإرادة أحد المتعاقدين وحده يمكن أن يؤدي إلى التعويض[229].\nالتعويضات التي يمكن أن تمنح بسبب عدم مراعاة ميعاد التنبيه لا تختلط بالتعويضات التي قد تترتب، من ناحية أخرى، عن الفسخ التعسفي للعقد الصادر بإرادة أحد الطرفين المتعاقدين[230]. ويسوغ للمحكمة، في سبيل تقدير ما إذا كان يوجد فسخ، أن تجري تحقيقا في ظروف إنهاء العقد[231]. ويلزم في جميع الأحوال، أن يتضمن الحكم صراحة ذكر المبرر الذي يدعيه الطرف الذي أنهى العقد.\nلتحديد التعويض، عندما يكون له محل، تلزم مراعاة العرف[232] وطبيعة الخدمات وأقدمية أدائها، وسن الأجير أو المستخدم والمخصومات المقتطعة والمدفوعات الحاصلة من أجل ترتيب معاش التقاعد، وعلى العموم كل الظروف التي تبرر وجود الخسارة الحاصلة وتحدد مداها[233].\nإذا طرأ تغيير في المركز القانوني لرب العمل، وعلى الأخص بسبب الإرث أو البيع أو الإدماج أو تحويل المشروع، أو تقديمه حصة في شركة فإن جميع عقود العمل الجارية في يوم حصول هذا التغيير تستمر بين المالك الجديد للمشروع وبين عماله وخدمه ومستخدميه[234].\nتوقف المشروع، لسبب آخر غير القوة القاهرة، لا يعفي صاحبه من الالتزام باحترام ميعاد التنبيه[235].\nلا يصح التنازل مقدما من الطرفين عن الحق الذي قد يثبت لأحدهما في طلب التعويضات وفقا لما تقضي به الأحكام السابقة[236].\nإذا رفعت المنازعات الناشئة عن تطبيق أحكام الفقرات السابقة أمام المحاكم المدنية أو محكمة الاستيناف[237] وجب التحقيق والحكم فيها على وجه السرعة.\nالامتياز المقرر بمقتضى البند 4 من[238] الفصل 1248 التالي يضمن التعويضات المنصوص عليها في هذا الفصل، سواء كانت بسبب عدم مراعاة ميعاد التنبيه أو بسبب الفسخ التعسفي للعقد.\nتطبق أحكام هذا الفصل، حتى في الحالة التي يرتبط فيها المستخدم بمقتضى عقود إجارة بعدة أرباب أعمال.",
  "755": "في تعهدات العمال أو الخدم وعمال المتاجر وخدام المحلات العمومية تعتبر الخمسة عشر يوما الأولى فترة تجربة، ويجوز خلالها لأي من الطرفين بمحض رغبته إبطال العقد، دون أن يلتزم بتعويض ما، وإذا أراد أحد الطرفين إبطال العقد، وجب عليه أن يعلم الآخر برغبته بيومين مقدما. وهنا يستحق المستخدم أجره على حسب عمله[239].\nويطبق كل ما سبق، إلا إذا قضى العرف[240] المحلي أو الاتفاق بخلافه.",
  "756": "في إجارة الخدمة يعتبر الشرط الفاسخ موجودا، دون حاجة للنص عليه، لصالح كل من المتعاقدين، إذا لم ينفذ المتعاقد الآخر التزاماته أو للأسباب الخطيرة الأخرى التي يترك تقديرها للقضاة.",
  "757": "للمخدوم الحق في فسخ العقد للمرض أو للإصابة التي تلحق خادمه أو مستخدمه نتيجة قوة قاهرة، على أن يدفع لهذا الأخير ما يستحقه بنسبة مدة خدمته[241].",
  "758": "إذا لم ينفذ أحد المتعاقدين التزاماته، أو إذا فسخها فجأة وفي وقت غير لائق ومن غير مبرر مقبول، ساغ إلزامه بالتعويضات لصالح المتعاقد الآخر، وهكذا فإن تغيب العامل قبل إنهاء عمله، ثم جاء بعد انقضاء مدة خدمته يطالب بالأجر عن المدة التي عمل خلالها، ساغ لرب العمل أن يدفع هذه المطالبة بالأضرار الناشئة له من انقطاع العمل ولا يلزمه إلا الفرق إن وجد. وكذلك إذا وقعت مخالفة العقد من رب العمل، وجبت عليه التعويضات للعامل.\nيحدد القاضي وجود الضرر ومداه، بحسب طبيعة العمل أو الخدمة ومع مراعاة ظروف الحال والعرف[242] المحلي.",
  "759": "تخضع الإجارة على الصنع، للأحكام العامة الواردة في الفصول 723 إلى 729 مع دخول الغاية والأحكام الآتية:",
  "760": "مقاولة البناء وغيرها من العقود التي يقدم فيها العامل أو الصانع المادة تعتبر بمثابة إجارة على الصنع.",
  "761": "يلتزم أجير الصنع بتقديم الآلات والأدوات اللازمة، ما لم يقض العرف أو الاتفاق بغير ذلك.",
  "762": "يسوغ لرب العمل ولورثته من بعده، فسخ العقد متى شاؤوا ولو بعد بدء العمل على أن يدفعوا لأجير الصنع قيمة المواد المعدة للعمل وما كان يمكنه أن يحصل عليه من ربح لو أن العمل قد تم.\nويسوغ للمحكمة أن تخفض مقدار هذا التعويض، وفقا لمقتضيات ظروف الحال.",
  "763": "يعتبر الشرط الفاسخ موجودا بحكم القانون، لصالح رب العمل بعد قيامه بإنذار أجير الصنع:\nأ - إذا أرجأ أجير الصنع الشروع في تنفيذه لأكثر من المدة المعقولة من غير عذر مقبول؛\nب - إذا كان مماطلا في التسليم.\nوكل ذلك ما لم يكن هناك خطأ يعزى لرب العمل.",
  "764": "إذا كان ضروريا لتنفيذ العمل، أن تؤدي رب العمل من جانبه شيئا معينا كان لأجير الصنع أن يدعوه صراحة لأدائه. وإذا مضت مدة معقولة، دون أن يؤدي رب العمل ما يجب عليه، كان لأجير الصنع الخيار بين أن يبقي على العقد وبين أن يطلب فسخه مع التعويض في الحالتين إن اقتضى الأمر ذلك.",
  "765": "إذا حدثت خلال تنفيذ الصنع، في المواد المقدمة من رب العمل أو في الأرض المخصصة للبناء أو في غير ذلك، عيوب أو نقائص من شأنها أن تهدد بالخطر حسن الصنع، وجب على أجير الصنع أن يخطر بها رب العمل فورا. وفي حالة الإهمال، يسأل عن كل الضرر الناجم عن تلك العيوب والنقائص، ما لم يكن من طبيعتها أن تخفى على عامل مثله.",
  "766": "عندما يقدم المقاول المادة، يكون ضامنا للصفات الواجبة في المواد التي يستخدمها.\nعندما يقدم رب العمل المادة، يجب على أجير الصنع أن يستعملها وفق ما تقتضيه أصول الصنعة ومن غير إهمال، كما يجب عليه أن يقدم حسابا عن استعمالها لرب العمل، وأن يرد إليه ما يتبقى منها.",
  "767": "يلتزم أجير الصنع بضمان عيوب ونقائص صنعه وتطبق على هذا الضمان أحكام الفصول 549 و553 و556.",
  "768": "يسوغ لرب العمل، في الحالة المنصوص عليها في الفصل السابق أن يرفض تسلم المصنوع أو إذا كان قد تسلمه أن يرده، خلال الأسبوع التالي لتسلمه، مع تحديد ميعاد معقول للعامل لقيامه بإصلاح العيب أو بتدارك الصفات الناقصة، إذا كان ذلك ممكنا. فإن انقضى هذا الميعاد دون أن ينفذ أجير الصنع التزامه كان لرب العمل الخيار بين:\nأولا - أن يجري بنفسه إصلاح العمل على نفقة أجير الصنع إذا كان إصلاحه ما زال ممكنا؛\nثانيا - أو أن يطلب إنقاص الثمن؛\nثالثا - أو أن يطلب فسخ العقد وترك الشيء لحساب من أجراه.\nوالكل مع حفظ الحق في التعويضات إن كان لها محل.\nإذا كان رب العمل قد قدم المواد الأولية لتنفيذ الصنع كان له الحق في استرجاع قيمتها. وتطبق مقتضيات الفصول 560 و561 و562 في الحالات المنصوص عليها في البندين الثاني والثالث أعلاه.",
  "769": "(ظهير 8 ديسمبر 1959) المهندس المعماري أو المهندس والمقاول المكلفان مباشرة من رب العمل يتحملان المسؤولية إذا حدث خلال العشر سنوات التالية لإتمام البناء أو غيره من الأعمال التي نفذاها أو أشرفا على تنفيذها إن انهار البناء كليا أو جزئيا، أو هدده خطر واضح بالانهيار بسبب نقص المواد أو عيب في طريقة البناء أو عيب في الأرض.\nالمهندس المعماري الذي أجرى تصميم البناء ولم يشرف على تنفيذ عملياته، لا يضمن إلا عيوب تصميمه.\nتبدأ مدة العشر سنوات من يوم تسلم المصنوع. ويلزم رفع الدعوى خلال الثلاثين يوما التالية ليوم ظهور الواقعة الموجبة للضمان، وإلا كانت غير مقبولة.",
  "770": "لا محل للضمان المذكور في الفصول 766 إلى 768، إذا كانت عيوب المصنوع قد تسببت[244] عن التعليمات الصريحة المعطاة من رب العمل برغم معارضة المقاول أو أجير الصنع.",
  "771": "إذا تسلم رب العمل مصنوعا معيبا، أو تنقصه الصفات المطلوبة مع علمه بعيوبه ولم يرده، ولم يتحفظ بشأن حقوقه على نحو ما هو مذكور في الفصل 768 كان هناك محل لتطبيق الفصل 553 المتعلق بعيوب الأشياء المنقولة التي بيعت وسلمت للمشتري.\nوتطبق أحكام الفصل 573 بالنسبة إلى الميعاد الذي يجوز لرب العمل فيه مباشرة حقه في الرجوع إذا لم يثبت أنه كان عالما بعيوب الشيء.",
  "772": "يبطل كل شرط موضوعه إنقاص أو إسقاط ضمان أجير الصنع لعيوب صنعه، وعلى الأخص إذا كان قد أخفى عن قصد هذه العيوب، أو كانت هذه العيوب ناشئة عن تفريطه[245] الجسيم.",
  "773": "في كل الحالات التي يقدم فيها العامل المادة، إذا هلك المصنوع كله أو بعضه نتيجة حادث فجائي أو قوة قاهرة، قبل تسلمه من رب العمل ومن غير مَطْـل من هذا الأخير في تسلمه فإن أجير الصنع لا يضمن هذا الهلاك ولكنه لا يحق له استرداد الثمن.",
  "774": "يلتزم رب العمل بتسلم المصنوع إذا كان مطابقا للعقد، كما يلتزم بنقله على نفقته إذا كان من شأنه أن ينقل.\nإذا ماطل رب العمل في تسلم الشيء من غير أن يكون ثمة خطأ من العامل تحمل تبعة هلاك هذا الشيء أو تعيبه، ابتداء من وقت ثبوت مَطْـله بإنذار يوجه إليه.",
  "775": "لا يستحق وفاء الثمن إلا بعد إنجاز العمل أو الفعل الذي هو محل العقد، وإذا حدد أداء الثمن على أساس وحدة زمنية أو جزء من العمل استحق الوفاء بعد إنجاز كل وحدة من وحدات الزمن أو العمل.",
  "776": "إذا انقطع إنجاز العمل، بسبب خارج عن إرادة المتعاقدين، لم يكن لأجير الصنع الحق في قبض الثمن إلا بنسبة ما أداه من عمل.",
  "777": "لا يسوغ لمن التزم بإجراء عمل في مقابل ثمن محدد وفقا لتصميم أو تقويم أجراهما أو قبلهما أن يطلب زيادة في الثمن إلا إذا كانت النفقات قد زادت بفعل رب العمل وكان هذا الأخير قد أذن صراحة في إجراء تلك الزيادات في النفقات.\nوكل ذلك ما لم يتفق الطرفان على خلافه.",
  "778": "يستحق الوفاء في المكان الذي يجب تسليم المصنوع فيه.",
  "779": "لأجير الصنع حق حَبْس الشيء الذي طلب منه إنجازه وغيره من الأشياء المملوكة لرب العمل الموجودة تحت يده حتى يستوفي ما قدمه وأجرة العمل. وذلك ما لم يكن الوفاء مؤجلا بمقتضى العقد، وفي هذه الحالة يسأل الأجير عن الشيء الذي حبسه وفقا للأحكام المقررة للمُرتَهِن الحيازي، بيد أنه إذا هلك الشيء بدون خطأ الأجير لم يكن له الحق في استيفاء الأجر لأن الأجر لا يستحق إلا في مقابل تسليم المصنوع.",
  "780": "للعمال والصناع المستخدمين في تشييد بناء أو أي عمل آخر يقع بالمقاولة الحق في إقامة دعوى مباشرة ضد من أجري الصنع لصالحه، في حدود المبالغ التي يكون ملتزما بها للمقاول عند إجراء أحدهم حجزا صحيحا عليها وما يلتزم به له بعد هذا الحجز.\nولهم حق الامتياز على هذه المبالغ بنسبة دين كل واحد منهم. ويجوز لرب العمل أن يدفع لهم هذه المبالغ مباشرة، إذا صدر بذلك حكم القاضي. والمقاولون الفرعيون الذين يستخدمهم المقاول الأصلي ومقدمو المواد الأولية ليست لهم أي دعوى مباشرة ضد رب العمل وليس لهم أن يباشروا إلا دعاوى مدينهم.",
  "781": "الوديعة عقد بمقتضاه يسلم شخص شيئا منقولا إلى شخص آخر يلتزم بحفظه وبرده بعينه.",
  "782": "إذا سلم شخص لآخر، على سبيل الوديعة، أشياء مثلية أو سندات لحاملها أو أسهما صناعية، ولكن مع الإذن للمودع عنده في استعمالها على أن يرد مثلها قدرا ونوعا وصنفا، فإن العقد الذي ينشأ في هذه الحالة يخضع للقواعد الخاصة بعارية الاستهلاك (القرض).",
  "783": "إذا سلم شخص لآخر مبلغا نقديا أو أوراقا بنكية أو غيرها من السندات التي تؤدي وظيفة النقود، على سبيل الوديعة المفتوحة من غير أن يضعها في مظروف مغلق أو ما يشبهه افترض أن المودع أذن للمودع عنده في استعمال الوديعة، ما لم يقم الدليل على عكس ذلك، ويتحمل المودع عنده هلاكها.",
  "784": "يجب لإجراء الوديعة ولقبولها توافر أهلية الالتزام. إلا أنه إذا قبل شخص متمتع بأهلية الالتزام الوديعة الصادرة من ناقص أهلية، فإنه يتحمل بكل الالتزامات الناشئة من الوديعة.",
  "785": "إذا أجريت الوديعة من شخص أهل إلى شخص آخر غير أهل، لم يكن للمودع الرشيد، إلا دعوى استحقاق الشيء المودع إذا كان موجودا في يد المودع عنده، فإن كان هذا الشيء قد خرج من يد المودع عنده لم يكن للمودع إلا دعوى الاسترداد، في حدود ما عاد على ناقص الأهلية من نفع. وذلك دون إخلال بما يقرره القانون في حالة الجرائم وأشباه الجرائم الواقعة من ناقص الأهلية.",
  "786": "لا يلزم، لصحة الوديعة بين المتعاقدين، أن يكون المودع مالكا للشيء المودع ولا أن يكون حائزا له على وجه مشروع.",
  "787": "تتم الوديعة برضى المتعاقدين وبتسليم الشيء المودع.\nيحصل التسليم بمجرد التراضي، إذا كان الشيء موجودا من قبل، بصفة أخرى بيد المودع عنده.",
  "788": "ومع ذلك، فإن الوعد بتسلم وديعة اقتضاها سفر المودع أو أي مبرر آخر مشروع، يعتبر التزاما من الواعد يمكن أن يؤدي إلى تحميله بالتعويضات في حالة عدم تنفيذه، ما لم يثبت أن أسبابا مشروعة وغير متوقعة حالت بينه وبين أداء ما تعهد به.",
  "789": "(ظهير 6 فبراير سنة 1951) إذا تجاوزت قيمة الوديعة 200 درهم لزم إثباتها بالكتابة[246]. ولا يسري هذا الحكم على الوديعة الاضطرارية. والوديعة الاضطرارية هي التي تجبر عليها حادثة كحريق أو غرق أو أي حدث آخر غير متوقع أو ناجم عن قوة قاهرة. ويمكن إثبات الوديعة الاضطرارية بأي وسيلة من وسائل الإثبات، أيا كانت قيمة الشيء المودع.",
  "790": "الأصل في الوديعة أن تكون بغير أجر، ومع ذلك، يستحق المودع عنده أجرا إذا كان قد اشترطه صراحة، أو إذا ظهر من ظروف الحال وعرف[247] المكان، أن المتعاقدين قد قصدا ضمنا منح المودع عنده أجرا معينا. وتكون هذه القرينة قانونية إذا كان من عادته تسلم الودائع بأجر.",
  "791": "على المودع عنده أن يسهر على حفظ الوديعة بنفس العناية التي يبذلها في المحافظة على أموال نفسه، مع استثناء ما هو مقرر في الفصل 807.",
  "792": "لا يحق للمودع عنده أن يحل شخصا آخر محله في حفظ الوديعة ما لم يؤذن له في ذلك صراحة، ومع استثناء حالة الضرورة العاجلة.\nوهو يسأل عمن يحله محله بغير إذن، ما لم يثبت أن الوديعة كانت ستهلك أيضا لو أنها بقيت بين يديه. أما إذا أذن له في أن يحل محله شخصا آخر، فإنه لا يسأل إلا في حالتين:\nأولا - إذا اختار شخصا لا تتوفر فيه الصفات الضرورية التي تجعل منه شخصا صالحا لتكليفه بحفظ الوديعة؛\nثانيا - إذا أعطى لمن أحله محله، ولو كان قد أحسن اختياره، تعليمات كانت هي السبب في حصول الضرر.\nوللمودع، في مواجهة المودع عنده الفرعي، دعوى مباشرة في جميع الأحوال التي كانت تثبت له فيها هذه الدعوى في مواجهة المودع عنده الأصلي، وذلك مع حفظ حقه في الرجوع على هذا الأخير.",
  "793": "إذا استعمل المودع عنده الوديعة أو تصرف فيها وذلك بدون إذن من المودع، كما إذا أعارها، أو كما إذا كانت الوديعة دابة فركبها، فإنه يضمن هلاكها أو تعيبها ولو حصل نتيجة قوة قاهرة أو حادث فجائي. وهو يضمن أيضا القوة القاهرة والحادث الفجائي، إذا اتجر في الشيء المودع. ولكنه يستحق حينئذ الربح الذي يستخلصه من هذا الشيء. وإذا لم يستعمل المودع عنده أو لم يتصرف إلا في جزء من الوديعة، فلا يسأل إلا عن هذا الجزء.",
  "794": "لا يجوز للمودع عنده أن يجبر المودع على استرداد الوديعة قبل الأجل المتفق عليه، ما لم تدعه إلى ذلك مبررات خطيرة.\nولكن يجب عليه أن يرد الوديعة للمودع بمجرد أن يطلب هذا منه ردها ولو كان الاتفاق قد حدد أجلا معينا لرد الوديعة.",
  "795": "يعتبر المودع عنده مماطلا في رد الوديعة بمجرد تأخره في القيام به بعد طلب المودع منه ذلك، ما لم تكن له مبررات مشروعة للتأخير، ومع ذلك فإن كانت الوديعة قد أجريت أيضا لمصلحة الغير، لم يسغ للمودع عنده أن يردها بدون إذنه.",
  "796": "إذا لم يحدد لرد الوديعة أجل، كان للمستودع أن يردها في أي وقت شاءه بشرط ألا يحصل منه ذلك الرد في وقت غير لائق، وبشرط أن يمنح المودع أجلا كافيا لاسترداد وديعته أو لاتخاذ ما تقتضيه الظروف من إجراءات.",
  "797": "يجب رد الوديعة في مكان إبرام العقد، فإن عين العقد مكانا آخر، التزم المودع عنده بإجراء الرد في هذا المكان. وتقع مصروفات نقل الوديعة وتسليمها على المودع.",
  "798": "على المودع عنده أن يرد الوديعة للمودع، أو لمن حصل الإيداع باسمه، أو لمن عينه العقد لتسلم الوديعة. وليس له أن يطلب من المودع إثبات ملكيته للشيء المودع.\nوللشخص الذي عينه العقد لتسلم الوديعة دعوى مباشرة في مواجهة المودع عنده من أجل إلزامه بتسليم الوديعة له.",
  "799": "إذا أجريت الوديعة من ناقص الأهلية أو ممن أشهر إفلاسه[248] قضاء لم يسغ رد الشيء المودع إلا لمن ينوب عنه قانونا، وذلك ولو كان نقص الأهلية أو الإفلاس[249] قد حصل بعد إجراء الوديعة.",
  "800": "لا ترد الوديعة، عند موت المودع، إلا لوارثه أو لمن ينوب قانونا عن هذا الوارث.\nوإذا تعدد الورثة، كان للمودع عنده الخيار بين أن يرفع الأمر للقاضي وإجراء ما يأمر به لإبعاد المسؤولية عنه، وبين أن يرد الوديعة للورثة كل بقدر نصيبه، وهنا يتحمل مسؤولية فعله. وإذا كان الشيء المودع غير قابل للتبعيض، وجب لتسلم الورثة إياه، اتفاقهم فيما بينهم على ذلك. وإذا كان من بينهم قاصرون أو غائبون، لم يسغ رد الوديعة إلا بإذن القاضي. فإذا لم يتفق الورثة، أو لم يحصلوا على إذن القاضي، كان للمودع عنده أن يبرئ ذمته بإيداع الشيء في المحل المخصص للأمانات على وفق ما يقضي به القانون. ويسوغ أيضا أن يلزمه القاضي بإجراء هذا الإيداع، بناء على طلب كل من له مصلحة.\nعند إعسار التركة، وعند وجود وصايا، يجب على المودع عنده رفع الأمر للقاضي.",
  "801": "يسري حكم الفصل السابق إذا حصلت الوديعة من عدة أشخاص بالاشتراك فيما بينهم ولم يتفق صراحة على إمكان رد الوديعة لأحد منهم أو لهم جميعا.",
  "802": "إذا أجريت الوديعة من وصي أو مقدم فقد صفته هذه عند إجراء الرد، لم يسغ رد الوديعة إلا لمن كان يمثله ذلك الوصي أو المقدم بشرط أن تتوفر فيه أهلية تسلمها، أو لمن خلف الوصي أو المقدم.",
  "803": "على المودع عنده أن يرد الشيء للمودع، ولو ادعى أحد من الغير حقا عليه، ما لم يكن قد حجز عليه ورفعت ضده دعوى الاستحقاق فإنه يجب عليه حينئذ أن يخطر المودع فورا بما حصل، ويجب إخراجه من الدعوى بمجرد إثباته أنه مودع عنده فقط.\nوإذا استمر النزاع إلى ما بعد الأجل المعين للوديعة حق له أن يستحصل على الإذن في إيداع الشيء بمحل الأمانات لحساب من يستحقه قانونيا.",
  "804": "على المودع عنده أن يرد ذات الشيء الذي تسلمه وتوابعه التي سلمت له معه في الحالة التي هو عليها، مع عدم الإخلال بما هو مقرر في الفصلين 808 و809.",
  "805": "على المودع عنده أن يرد مع الوديعة كل ما حصل عليه من ثمارها المدنية والطبيعية.",
  "806": "يضمن المودع عنده هلاك الشيء أو تعيبه الحاصل بفعله أو بإهماله.\nوهو يسأل أيضا عن عدم اتخاذ الاحتياطات التي يشترطها العقد. وكل شرط يخالف ذلك يكون عديم الأثر.",
  "807": "يضمن المودع عنده الهلاك أو الضرر الناتج من أي سبب كان يمكنه التحرز منه:\nأولا - عندما يأخذ أجرا عن حفظ الوديعة؛\nثانيا - عندما يتسلم الودائع بحكم مهنته أو وظيفته.",
  "808": "المودع عنده لا يضمن:\nأولا - الهلاك أو التعيب الحاصل بفعل الطبيعة، أو نتيجة عيب في الأشياء المودعة أو بسبب إهمال المودع؛\nثانيا - حالات القوة القاهرة أو الحادث الفجائي، ما لم يكن مماطلا في رد الوديعة، أو ما لم تكن القوة القاهرة قد تسببت بخطإه أو بخطأ الأشخاص الذين يسأل عنهم. ويتحمل عبء إثبات القوة القاهرة أو إثبات عيب الأشياء المودعة، إذا كان يأخذ أجرا عن الوديعة، أو إذا كان قد تسلم الوديعة بحكم مهنته أو وظيفته.",
  "809": "يكون باطلا كل اتفاق من شأنه أن يحمل المودع عنده تبعة الحادث الفجائي أو القوة القاهرة مع استثناء الحالات المنصوص عليها في الفصلين 782 و783 وحالة الوديعة المأجورة. ولا يعمل بهذا الحكم إلا فيما بين غير المسلمين.",
  "810": "المودع عنده الذي ينتزع منه الشيء بقوة قاهرة، ويأخذ عوضا عنه شيئا آخر أو مبلغا من النقود، يلتزم برد ما أخذ عوضا.",
  "811": "إذا فوت وارث المودع عنده، بحسن نية، الشيء المودع على سبيل المُعاوضة أو التبرع، كان للمودع أن يسترده من بين يدي المفوت إليه، ما لم يفضل الرجوع بقيمته على الوارث المفوت. ويلتزم أيضا بالتعويضات إن كان سيء النية.",
  "812": "إذا تعدد المودع عندهم، كانوا متضامنين فيما بينهم في الالتزامات والحقوق الناشئة من الوديعة، وفقا للقواعد المقررة للوكالة، وذلك ما لم يوجد شرط يقضي بخلافه.",
  "813": "القول قول المودع عنده بيمينه في واقعة الوديعة ذاتها، أو في الشيء المودع، أو في رده لمالكه أو لمن يحق له تسلمه. ولا يسري هذا الحكم إذا كانت الوديعة ثابتة في محرر رسمي أو عرفي.\nويبطل كل شرط من شأنه أن يعفي المودع عنده من اليمين في الحالات السابقة.\nوليس للمودع عنده أن يتمسك بالأحكام السابقة، إذا كان قد أساء استعمال الشيء المودع أو فوته على المودع لفائدة نفسه.",
  "814": "على المودع أن يدفع للمودع عنده المصروفات الضرورية التي أنفقها في حفظ الوديعة وأن يدفع له الأجر المتفق عليه أو الذي يحدده العرف إن اقتضى الحال ذلك. كما أن على المودع أن يعوض المودع عنده عن الأضرار التي يكون الشيء المودع قد سببها له. أما المصروفات النافعة فإنه لا يلتزم بدفعها إلا في الأحوال ووفقا للأحكام المقررة للفضالة (تصرفات الفُضولي).\nولا يلتزم المودع بدفع أي تعويض عن الأضرار التي تلحق المودع عنده:\nأولا - إذا كانت هذه الأضرار ناشئة بسبب خطأ المودع عنده؛\nثانيا - إذا أخطر المودع عنده على وجه معتبر قانونا، بالضرر الذي يتهدده ولم يتخذ مع ذلك ما يلزم من الاحتياطات لدرئه.",
  "815": "إذا تعدد المودعون، التزم كل منهم تجاه المودع عنده بنسبة مصلحته في الوديعة، ما لم يشترط غير ذلك.",
  "816": "إذا انقضى عقد الوديعة قبل الأجل المحدد له، لم يستحق المودع عنده الأجر المتفق عليه إلا بنسبة الوقت الذي بقي الشيء خلاله في حفظه، ما لم يتفق على غير ذلك.",
  "817": "ليس للمودع عنده حبس الوديعة إلا من أجل المصروفات الضرورية التي أنفقها في حفظها، وليس له حق حَبْسها ضمانا لأي دين آخر.",
  "818": "إيداع الشيء المتنازع عليه بين يدي أحد من الغير يسمى حراسة. ويجوز أن ترد الحراسة على المنقولات أو العقارات، وهي تخضع لأحكام الوديعة الاختيارية ولأحكام هذا الباب.",
  "819": "ويجوز، بموافقة الأطراف المعنية إسناد الحراسة لشخص يتفقون عليه فيما بينهم. كما يجوز الأمر بها من القاضي في الأحوال التي يحددها قانون المسطرة.",
  "820": "يجوز أن لا تكون الحراسة بالمجان.",
  "821": "للحارس حفظ الشيء وإدارته. ويجب عليه أن يجعله يدر كل الثمار التي في إمكانه أن يدرها.",
  "822": "وليس له أن يقوم بأي عمل من أعمال التفويت إلا ما هو ضروري لمصلحة الأشياء المعهود إليه بحراستها.",
  "823": "إذا كانت الأشياء الخاضعة للحراسة معرضة للتعيب، جاز للقاضي أن يأذن في بيعها وفقا للإجراءات المتطلبة في بيع الشيء المرهون، وتقع الحراسة على الثمن.",
  "824": "على الحارس أن يرد الشيء بدون أجل لمن يعينه الخصوم أو القضاء ويتحمل بشأن هذا الرد، بنفس الالتزامات التي يتحمل بها المودع عنده المأجور.",
  "825": "يضمن الحارس القوة القاهرة والحادث الفجائي، إذا كان مماطلا في رد الشيء أو إذا كان خصما في الدعوى ورضي أن يقوم بمهمة الحارس المؤقت، أو إذا كانت القوة القاهرة قد تسببت بفعله أو بخطإه أو بفعل أو بخطأ الأشخاص الذين يسأل عنهم.",
  "826": "على الحارس أن يقدم حسابا مضبوطا عن كل ما تسلمه وكل ما أنفقه مع ما يؤيده من الحجج، ومع بيان المقدار. وإذا لم تكن حراسته على سبيل التبرع، فإنه يسأل عن كل خطأ يرتكب في إدارته، وفقا للقواعد المقررة للوكالة.",
  "827": "إذا تعدد الحراس كانوا متضامنين بقوة القانون، وفقا للقواعد المقررة للوكالة.",
  "828": "على الخصم الذي يرد إليه الشيء أن يدفع للمودع عنده المصروفات الضرورية والنافعة التي أنفقها بحسن نية وبدون إفراط، وكذلك الأجور المتفق عليها أو التي يحددها القاضي. وإذا كانت الوديعة اختيارية، كان للمودع عنده حق مطالبة جميع المودعين، بالمصروفات والأجور على نسبة ما لكل واحد منهم من فائدة في الوديعة.",
  "829": "العارية نوعان: عارية الاستعمال وعارية الاستهلاك أو القرض.",
  "830": "عارية الاستعمال عقد بمقتضاه يسلم أحد طرفيه للآخر شيئا، لكي يستعمله خلال أجل معين أو في غرض محدد، على أن يرده بعينه. وفي العارية يحتفظ المعير بملكية الشيء المستعار وبحيازته القانونية. وليس للمستعير إلا مجرد استعماله.",
  "831": "يلزم، لإعارة الشيء، توفر أهلية التصرف فيه على سبيل التبرع.\nوليس للأوصياء والمقدمين ومن يتولون إدارة أموال الغير أن يعيروا الأشياء التي يكلفون بإدارتها.",
  "832": "يسوغ أن ترد عارية الاستعمال على الأشياء المنقولة والعقارية.",
  "833": "تتم عارية الاستعمال بتراضي الطرفين وبتسليم الشيء إلى المستعير.",
  "834": "غير أن الوعد بالإعارة، لسبب معلوم من الواعد، يتضمن التزاما، من الممكن أن ينقلب إلى تعويض إذا لم يف بوعده، وذلك ما لم يثبت أن حاجة غير متوقعة قد حالت بينه وبين أداء التزامه، أو أن ظروف المستعير المالية قد ساءت إلى حد كبير منذ العهد الذي قطعه الواعد على نفسه.",
  "835": "من أسس عارية الاستعمال أن تكون على وجه التبرع.",
  "836": "يلتزم المستعير بأن يعتني بالمحافظة على الشيء المعار.\nوليس له أن يعهد بأمر المحافظة عليه إلى شخص آخر، ما لم تكن ثمة ضرورة عاجلة. وعند الإخلال بهذا الالتزام، يتحمل تبعة الحادث الفجائي والقوة القاهرة.",
  "837": "ليس للمستعير أن يستعمل الشيء المعار، إلا بالكيفية وفي الحدود المبينة بمقتضى العقد أو العرف[250]، وفقا لما تقتضيه طبيعته.",
  "838": "للمستعير أن يستعمل الشيء بنفسه، أو أن يعيره بدوره لأحد من الغير، أو أن يمنحه استعماله على سبيل التبرع، ما لم تكن العارية قد تمت بالنظر لشخص المستعير أو لغرض محدد على وجه التخصيص.",
  "839": "ليس للمستعير أن يكري الشيء المعار ولا أن يرهنه رهنا حيازيا ولا أن يفوته بغير إذن المعير.",
  "840": "على المستعير، عند انتهاء الأجل المتفق عليه، أن يرد ذات الشيء الذي تسلمه مع توابعه والزيادات التي طرأت عليه منذ العارية. وهو لا يجبر على هذا الرد قبل انتهاء ذلك الأجل.",
  "841": "إذا أجريت العارية من غير تحديد للزمن لم يلتزم المستعير برد الشيء إلا بعد استعماله إياه على النحو المتفق عليه، أو على حسب العرف[251].\nفإذا أجريت العارية من غير تحديد للغرض الذي يستعمل الشيء فيه، كان للمعير أن يطلب رده في أي وقت شاءه، ما لم يقض العرف[252] بغير ذلك.",
  "842": "غير أنه يسوغ للمعير أن يلزم المستعير برد الشيء ولو قبل الأجل أو الاستعمال المتفق عليه:\nأولا - إذا كانت له حاجة عاجلة وغير متوقعة؛\nثانيا - إذا أساء المستعير استعماله، أو استعمله على نحو يخالف النحو الذي حدده العقد؛\nثالثا - إذا قصر في اتخاذ ما يتطلبه من أوجه العناية.",
  "843": "إذا منح المستعير لأحد من الغير استعمال الشيء أو فوته بكيفية ما لفائدة شخص آخر كانت للمعير، في مواجهة هذا الشخص، دعوى مباشرة في نفس الأحوال التي تثبت له فيها هذه الدعوى إزاء المستعير.",
  "844": "على المستعير أن يرد الشيء في المكان الذي سلم إليه فيه، ما لم يوجد شرط يقضي بخلاف ذلك.",
  "845": "على المستعير مصروفات رد العارية ومصروفات تسلمها. وعليه أيضا:\nأولا - مصروفات الصيانة المعتادة؛\nثانيا - المصروفات اللازمة لاستعمال الشيء.",
  "846": "إلا أن للمستعير الحق في أن يسترد المصروفات العاجلة وغير المعتادة التي اضطر لإنفاقها من أجل الشيء المستعار قبل أن يخطر بها المعير. ويثبت له حق حَبْس هذا الشيء ضمانا لتلك المصروفات. بيد أنه إذا كان المستعير مماطلا في رد الشيء، لم يكن له الحق في استرداد المصروفات التي أنفقها خلال فترة مَطْـله.",
  "847": "في غير الحالات المنصوص عليها في الفصول السابقة، لا يثبت للمستعير حق حَبْس الشيء المعار ضمانا لحقوقه على المعير.",
  "848": "إذا لم تثبت عارية الاستعمال بمقتضى حجة رسمية أو عرفية، كان القول قول المستعير بيمينه، بالنسبة إلى رد الشيء المستعار. وللمستعير أن يعفي نفسه من حلف اليمين بإقامته الدليل على حصول الرد. أما إذا أثبتت عارية الاستعمال بمقتضى حجة، رسمية كانت أو عرفية، فإن ذمة المستعير لا تبرأ إلا بالدليل الكتابي.",
  "849": "لا يضمن المستعير هلاك الشيء المعار أو تعيبه الناشئ من استعماله إياه، إذا كان هذا الاستعمال عاديا أو مطابقا لاتفاق الطرفين، وإذا ادعى المعير أن المستعير أساء استعمال الشيء، وجب عليه أن يقيم الدليل على صحة ادعائه.",
  "850": "يضمن المستعير تعيب الشيء المعار وهلاكه الحاصلين نتيجة حادث فجائي أو قوة قاهرة، إذا أساء استعمال الشيء المعار، أو على الخخصوص:\nأولا - إذا استعمل الشيء استعمالا يخالف ما تقتضيه طبيعته أو يحدده الاتفاق؛\nثانيا - إذا ماطل في رد الشيء؛\nثالثا - إذا قصر في اتخاذ الاحتياطات اللازمة لحفظ الشيء، أو إذا تصرف فيه لصالح أحد من الغير بدون إذن المعير عندما تكون العارية قد أجريت بالنظر إلى شخصه.",
  "851": "يكون باطلا كل اشتراط من شأنه أن يحمل المستعير تبعة الحادث الفجائي.\nويبطل أيضا الاشتراط الذي بمقتضاه يشترط المستعير مقدما عدم مسؤوليته عن فعله أو خطإه.",
  "852": "تثبت للمستعير على المعير دعوى التعويض:\nأولا - إذا استحق الشيء لأحد من الغير أثناء استعماله إياه؛\nثانيا - إذا كان بالشيء المستعار عيوب أدت إلى إلحاق الضرر بمن يستعمله.",
  "853": "غير أن المعير لا يكون مسؤولا:\nأولا - إذا كان يجهل سبب الاستحقاق أو العيوب الخفية في الشيء؛\nثانيا - إذا بلغت العيوب أو الأخطار من الظهور حدا بحيث أنه كان من السهل على المستعير تبينها؛\nثالثا - إذا كان قد أخطر المستعير بوجود هذه العيوب أو الأخطار أو الأسباب التي قد تؤدي إلى الاستحقاق؛\nرابعا - إذا كان الضرر قد تسبب فقط عن فعل المستعير أو خطإه.",
  "854": "تنفسخ عارية الاستعمال بموت المستعير. غير أن الالتزامات الناشئة عنها تنتقل إلى تركته. ويتحمل ورثته شخصيا بالالتزامات الناشئة عن فعلهم والمتعلقة بالشيء المستعار.",
  "855": "دعاوى كل من المعير والمستعير على الآخر، الناشئة بمقتضى الفصول 836 و837 و839 و841 و846 و852 تتقادم بمضي ستة أشهر. ويبدأ سريان هذا الأجل بالنسبة إلى المعير من وقت رد الشيء إليه، وبالنسبة إلى المستعير من وقت انتهاء العقد.",
  "856": "عارية الاستهلاك أو القرض عقد بمقتضاه يسلم أحد الطرفين للآخر أشياء مما يستهلك بالاستعمال أو أشياء منقولة أخرى، لاستعمالها، بشرط أن يرد المستعير، عند انقضاء الأجل المتفق عليه، أشياء أخرى مثلها في المقدار والنوع والصفة.",
  "857": "وتنعقد عارية الاستهلاك كذلك عندما يوجد من النقود أو كمية من الأشياء المثلية بين يدي المدين على وجه الوديعة أو بأي صفة أخرى ويأذن له الدائن بالاحتفاظ بما بين يديه على سبيل القرض. وهنا يتم العقد بمجرد اتفاق الطرفين على الشروط الأساسية للقرض.",
  "858": "يلزم للإقراض توافر أهلية التفويت للأشياء محل القرض.\nليس للأب[253]، بدون إذن القاضي، أن يقرض أو يقترض لنفسه مال ابنه الذي في حجره. وإذا رخص القاضي للأب في شيء من ذلك، وجب عليه أن يأمر بكل ما يراه لازما من الضمانات التي من شأنها أن تصون مصالح القاصر صيانة تامة. ويطبق نفس الحكم على الوصي والمقدم ومدير الشخص المعنوي، بالنسبة إلى الأموال أو القيم المملوكة للأشخاص الذين يديرون أموالهم.",
  "859": "يصح أن يرد القرض على:\nأ - الأشياء المنقولة، كالحيوانات والملابس والأثاث؛\nب - الأشياء التي تستهلك بالاستعمال، كالأطعمة والنقود.",
  "860": "إذا تسلم المقترض، بدلا من النقود المتفق على إقراضها، أوراقا مالية أو سلعا، فإن المبلغ المقترض يحسب بسعر السوق لهذه الأوراق المالية أو السلع في مكان التسليم وزمانه.\nوكل اشتراط مخالف لذلك يكون باطلا.",
  "861": "ينقل القرض إلى المقترض ملكية الأشياء أو القيم المقترضة ابتداء من الوقت الذي يتم فيه العقد بتراضي الطرفين، ولو قبل تسليم الأشياء المقترضة.",
  "862": "يكون المقترض ضامنا للشيء المقترض، ابتداء من وقت تمام العقد ولو قبل تسليمه إياه، ما لم يشترط غير ذلك.",
  "863": "غير أن للمقرض الحق في أن يحبس بين يديه الشيء المقترض إذا كانت أحوال المقترض قد ساءت منذ العقد بحيث يتوقع ضياع مال القرض كله أو بعضه. ويثبت له هذا الحق في الحبس ولو كان سوء حالة المقترض يرجع إلى وقت سابق على العقد، إذا لم يطلع عليه المقرض إلا بعده.",
  "864": "يضمن المقرض العيوب الخفية في الشيء المقترض واستحقاقه، وفقا للأحكام المقررة في باب البيع.",
  "865": "على المقترض أن يرد مثل ما تسلمه قدرا وصفة، ولا يلزمه غير ذلك.",
  "866": "لا يسوغ إجبار المقترض على رد ما هو ملتزم به قبل الأجل المحدد بمقتضى العقد أو العرف[254]. ويسوغ له رده قبل حلول الأجل[255]، ما لم يتناف ذلك مع مصلحة المقرض.",
  "867": "إذا لم يحدد لدفع القرض أجل، وجب على المقترض الوفاء عند طلب المقرض.\nإذا اشترط أن المقترض يرد القدر الذي اقترضه عندما يمكنه ذلك، أو من أول مال يستطيع التصرف فيه، فإن المحكمة تحدد، وفقا لظروف الحال ميعادا معقولا للرد.",
  "868": "على المقترض أن يرد الأشياء المقترضة في نفس مكان انعقاد القرض ما لم يتفق على غير ذلك.",
  "869": "تقع مصروفات تسلم الأشياء المقترضة وردها على عاتق المقترض.",
  "870": "اشتراط الفائدة بين المسلمين باطل ومبطل للعقد الذي يتضمنه سواء جاء صريحا، أو اتخذ شكل هدية أو أي نفع آخر للمقرض أو لأي شخص غيره يتخذ وسيطا له.",
  "871": "وفي الحالات الأخرى، لا تستحق الفوائد إلا إذا كانت قد اشترطت كتابة.\nويفترض هذا الاشتراط إذا كان أحد الطرفين تاجرا.",
  "872": "فوائد المبالغ التي تتضمنها الحسابات الجارية تستحق بقوة القانون على من يكون مدينا بها من الطرفين، ابتداء من يوم ثبوت تقديمها[256].",
  "873": "لا يسوغ حساب الفوائد إلا على أساس سعر يعين عن سنة كاملة[257].\nويسوغ، في الشؤون التجارية، احتساب الفوائد بالشهر. ولكن لا يسوغ اعتبارها من رأس المال المنتج للفوائد، حتى في الحسابات الجارية إلا بعد انتهاء كل نصف سنة.",
  "874": "يكون باطلا، بين كل الناس اشتراط كون الفوائد غير المدفوعة تضم في آخر كل عام إلى رأس المال الأصلي، لتصبح هي نفسها منتجة للفوائد.",
  "875": "في الشؤون المدنية والتجارية، يحدد السعر القانوني للفوائد والحد الأقصى للفوائد الاتفاقية بمقتضى نص قانوني خاص.",
  "876": "إذا تجاوزت الفوائد الاتفاقية الحد الأقصى المحدد على نحو ما هو مبين في الفصل السابق، كان للمقترض الحق في أن يدفع أصل الدين بعد عام من تاريخ العقد. وكل شرط يخالف ذلك يكون عديم الأثر، غير أنه يجب على المقترض إخطار الدائن كتابة بعزمه على الدفع قبل إجرائه بثلاثة أشهر على الأقل. ويتضمن هذا الإخطار بقوة القانون تنازلا من المقترض عما يكون قد منح له من أجل أطول.\nولا يسري هذا الفصل على الديون المعقودة من الدولة والبلديات وغيرها من الأشخاص المعنوية على نحو ما هو مقرر بمقتضى القانون.",
  "877": "يسري حكم الفصل 876 سواء اشترطت الفوائد مباشرة، أو اتخذ اشتراطها شكل الرهن الحيازي العقاري أو شكل بيع الثـُّـنْـيَـا الذي يستر الربا، أو شكل اقتطاع من رأس المال وقت القرض أو شكل عمولة أخذت زيادة على الفوائد.",
  "878": "من يستغل حاجة شخص آخر أو ضعف إدراكه أو عدم تجربته فيجعله يرتضي من أجل الحصول على قرض أو لتجديد قرض قديم عند حلول أجله فوائد أو منافع أخرى تتجاوز إلى حد كبير السعر العادي للفوائد وقيمة الخدمة المؤداة، وفقا لمقتضيات المكان وظروف التعامل، يمكن أن يكون محلا للمتابعة الجنائية. ويسوغ إبطال الشروط والاتفاقات المعقودة بمخالفة حكم هذا الفصل بناء على طلب الخصم، بل حتى من تلقاء نفس المحكمة. ويجوز إنقاص السعر المشترط، ويحق للمدين استرداد ما دفعه زيادة على السعر الذي تحدده المحكمة على أساس أنه دفع ما ليس مستحقا عليه وإذا تعدد الدائنون، كانوا مسؤولين على سبيل التضامن.",
  "879": "الوَكالة عقد بمقتضاه يكلف شخص شخصا آخر بإجراء عمل مشروع لحسابه، ويسوغ إعطاء الوَكالة أيضا لمصلحة الموكل والوكيل، أو لمصلحة الموكل والغير، بل ولمصلحة الغير وحده.",
  "880": "يلزم لصحة الوَكالة، أن يكون الموكل أهلا لأن يجري بنفسه التصرف الذي يكون محلا لها. ولا تلزم نفس الأهلية في الوكيل، حيث يكفي فيه أن يكون متمتعا بالتمييز وبقواه العقلية، ولو لم تكن له صلاحية إجراء التصرف في حق نفسه. فيسوغ للشخص أن يجري باسم الغير ما لا يستطيع أن يجريه بالأصالة عن نفسه.",
  "881": "تبطل الوَكالة:\nأ - إذا كان محلها مستحيلا أو مبهما إبهاما فاحشا؛\nب - إذا كان محلها أعمالا مخالفة للنظام العام أو للأخلاق الحميدة أو للقوانين المدنية أو الدينية.",
  "882": "تعتبر الوَكالة كأن لم تكن إذا كان محلها عملا لا يجوز إجراؤه بطريق النيابة كأداء اليمين.",
  "883": "تتم الوَكالة بتراضي الطرفين.\nويسوغ أن يكون رضى الموكل صريحا أو ضمنيا، مع استثناء الحالات التي يتطلب القانون فيها شكلا خاصا.\nكما أنه يسوغ أن يأتي قبول الوكيل ضمنيا، وأن يستنتج من تنفيذه ما وكل فيه مع استثناء الحالات التي يتطلب القانون فيها قبولا صريحا.",
  "884": "غير أنه لا يفترض في الخدم أنهم موكلون في شراء الحاجيات الضرورية لمنازل مخدوميهم بالسلف، ما لم يثبت أن من عادة المخدوم الشراء بالسلف.",
  "885": "إذا حصل الإيجاب بالوَكالة لشخص يمتهن القيام بالخدمات التي تتضمنها اعتبر قابلا الإيجاب، ما لم يخطر الموجب برفضه إياه فور تسلمه. ويجب عليه، برغم رفضه، اتخاذ الإجراءات العاجلة التي يتطلبها صالح من كلفه بالعمل. وإذا أرسلت إليه بضائع، وجب عليه إيداعها في مكان أمين واتخاذ ما يلزم من الإجراءات الضرورية للمحافظة عليها، على نفقة الموجب، وذلك إلى أن يتمكن هذا الأخير من رعاية أمره بنفسه. فإن كان في التأخير خطر، وجب عليه أن يعمل على بيع السلع المرسلة بواسطة السلطة القضائية بعد إثبات حالتها.",
  "886": "إذا وكل شخص شخصا آخر بمكتوب أو ببرقية أو بواسطة رسول وقبل الوكيل الوَكالة بلا شرط ولا تحفظ، اعتبرت الوَكالة منعقدة في محل إقامة الوكيل.",
  "887": "يجوز إعطاء الوَكالة في شكل يخالف الشكل المتطلب لإجراء التصرف الذي يكون محلا لها.",
  "888": "الوَكالة بلا أجر، ما لم يتفق على غير ذلك، غير أن مجانية الوَكالة لا تفترض:\nأولا - إذا كلف الوكيل بإجراء عمل داخل في حرفته أو مهنته؛\nثانيا - بين التجار فيما يتعلق بالمعاملات التجارية؛\nثالثا - إذا قضى العرف[258] بإعطاء أجر عن القيام بالأعمال التي هي محل الوَكالة.",
  "889": "يسوغ إعطاء الوَكالة بشرط، أو ابتداء من وقت معين، أو إلى أجل محدد.",
  "890": "يجوز أن تكون الوَكالة خاصة أو عامة.",
  "891": "الوَكالة الخاصة هي التي تعطى من أجل إجراء قضية أو عدة قضايا أو التي لا تمنح الوكيل إلا صلاحيات خاصة.\nوهي لا تمنح الوكيل صلاحية العمل إلا بالنسبة إلى القضايا أو التصرفات التي تعينها وكذلك توابعها الضرورية وفقا لما تقتضيه طبيعتها أو العرف[259] المحلي.",
  "892": "وكالة التقاضي وكالة خاصة. وهي تخضع لمقتضى أحكام هذا القانون وهي لا تخول صلاحية العمل إلا بالنسبة إلى الأعمال التي تعينها، وعلى الأخص فهي لا تعطي الصلاحية في قبض الدين أو إجراء الإقرار أو الاعتراف بالدين أو إجراء الصلح، ما لم يصرح بمنحها للوكيل.",
  "893": "الوَكالة العامة هي التي تمنح الوكيل صلاحية غير مقيدة لإدارة كل مصالح الموكل، أو هي التي تمنحه صلاحيات عامة غير مقيدة في قضية معينة.\nوهي تمنح الصلاحية لإجراء كل ما تقتضيه مصلحة الموكل وفقا لطبيعة المعاملة وعرف[260] التجارة، وعلى الأخص قبض ما هو مستحق له، ودفع ديونه، واتخاذ كل الإجراءات التحفظية، ورفع دعاوى الحيازة (الدعوى التصرفية)، ورفع الدعاوى أمام القضاء على المدينين وحتى التعاقد الذي من شأنه تحميل الموكل بالالتزامات في الحدود التي يقتضيها تنفيذ المعاملات التي كلف الوكيل بإجرائها.",
  "894": "لا يجوز للوكيل، أيا ما كان مدى صلاحياته، بغير إذن صريح من الموكل توجيه اليمين الحاسمة، ولا إجراء الإقرار القضائي، ولا الدفاع أمام القضاء في جوهر الدعوى، ولا قبول الحكم أو التنازل عنه، ولا قبول التحكيم أو إجراء الصلح، ولا الإبراء من الدين، ولا تفويت عقار أو حق عقاري ولا إنشاء الرهن رسميا كان أم حيازيا، ولا شطب الرهن أو التنازل عن الضمان ما لم يكن ذلك في مقابل الوفاء بالدين، ولا إجراء التبرعات ولا شراء أو تفويت لأصل تجاري أو تصفيته. ولا التعاقد على إنشاء شركة أو شياع، وكل ذلك ماعدا الحالات التي يستثنيها القانون صراحة.",
  "895": "على الوكيل أن ينفذ بالضبط المهمة التي كلف بها. فلا يسوغ أن يجري أي عمل يتجاوز أو يخرج عن حدود الوَكالة.",
  "896": "إذا أنجز الوكيل القضية التي كلف بها بشروط أفضل مما هو مذكور في الوَكالة، فإن الفرق يكون لفائدة الموكل.",
  "897": "إذا ثار الشك حول مدى الصلاحيات الممنوحة للوكيل أو شروطها كان القول قول الموكل بيمينه.",
  "898": "إذا عين الموكل بعقد واحد ومن أجل نفس القضية عدة وكلاء، لم يجز لهؤلاء أن يعملوا منفردين، ما لم يكونوا مأذونين صراحة في ذلك. فلا يسوغ لأي منهم أن يجري أي عمل في غياب الآخر، حتى لو استحال على هذا الآخر الاشتراك معه في إجرائه.\nو لا يسري هذا الحكم:\nأولا - إذا تعلقت الوَكالة بالدفاع أمام القضاء، أو برد الوديعة أو بدفع دين مستحق الأداء وغير متنازع فيه، أو باتخاذ إجراء تحفظي في مصلحة الموكل، أو بعمل عاجل من شأن تركه أن يضر بهذا الأخير؛\nثانيا - في الوَكالة القائمة بين التجار لأعمال التجارة.\nوفي هاتين الحالتين، يسوغ لأحد الوكلاء أن ينفرد دونهم بإنجاز العمل، ما لم يصرح بالعكس.",
  "899": "إذا عين عدة وكلاء بعقود متفرقة من أجل نفس القضية، كان لأي منهم أن ينفرد بالعمل في غياب الآخرين.",
  "900": "لا يسوغ للوكيل أن يوكل تحت يده شخصا آخر في تنفيذ الوَكالة، ما لم يمنح الصلاحية في ذلك صراحة أو ما لم تستخلص هذه الصلاحية من طبيعة القضية أو من ظروف الحال.\nغير أن الوكيل العام ذا الصلاحية التامة يعتبر مأذونا في أن يوكل تحت يده كليا أو جزئيا.",
  "901": "الوكيل مسؤول عمن يوكل تحت يده. غير أنه إذا رخص له في أن يوكل تحت يده شخصا آخر دون أن يعين هذا الشخص، فإنه لا يكون مسؤولا إلا إذا اختار لذلك شخصا لا تتوفر فيه الصفات المطلوبة لإنجاز الوَكالة أو إذا كان قد أحسن الاختيار ولكنه أعطى لمن وكله تحت يده تعليمات كانت هي السبب في حدوث الضرر، أو إذا كان لم يراقبه مع أن مراقبته كانت ضرورية وفقا لمقتضيات ظروف الحال.",
  "902": "في جميع الأحوال، يلتزم نائب الوكيل مباشرة تجاه الموكل في نفس الحدود التي يلتزم فيها الوكيل، وتكون له نفس حقوق هذا الأخير.",
  "903": "على الوكيل أن يبذل، في أدائه المهمة التي كلف بها، عناية الرجل المتبصر حي الضمير. وهو مسؤول عن الضرر الذي يلحق الموكل نتيجة انتفاء هذه العناية كما إذا لم ينفذ اختيارا مقتضى الوَكالة أو التعليمات التي تلقاها، أو إذا لم يتخذ ما يقتضيه العرف[261] في المعاملات.\nوإذا توفرت للوكيل أسباب خطيرة تدفعه إلى مخالفة التعليمات التي تلقاها أو إلى مخالفة ما جرى عليه العرف[262]، وجب عليه أن يبادر بإخطار الموكل بها في أقرب فرصة، وعليه أن ينتظر تعليماته، ما لم يكن في الانتظار خطر.",
  "904": "الالتزامات المذكورة في الفصل السابق يجب أن تراعى على شكل أكثر صرامة:\nأولا - عندما تكون الوَكالة بأجر؛\nثانيا - عندما تباشر الوَكالة في مصلحة قاصر أو ناقص أهلية أو شخص معنوي.",
  "905": "إذا تعيبت الأشياء التي تسلمها الوكيل لحساب الموكل، أو ظهرت عليها بوادر العوار على نحو يمكن معه التعرف عليها من شكلها الخارجي، وجب على الوكيل إجراء ما يلزم للمحافظة على حقوق الموكل في مواجهة المكارى (صاحب النقل) أو غيره من المسؤولين.\nوإذا كان في التأخير خطر أو إذا حدث التعيب على نحو لا يستطيع الوكيل معه الانتظار ريثما يرجع إلى الموكل، فإنه يجوز للوكيل، بل يجب عليه عندما تقتضيه مصلحة الموكل أن يعمل على بيع الأشياء بواسطة السلطة القضائية، بعد إثبات حالتها، وعليه أن يخطر فورا الموكل بكل ما يكون قد أجراه.",
  "906": "على الوكيل أن يعلم الموكل بكل الظروف التي قد يكون من شأنها أن تحمله على إلغاء الوَكالة أو تعديلها.",
  "907": "على الوكيل، بمجرد إنهاء مهمته، أن يبادر بإخطار الموكل بها، مع إضافة كل التفاصيل اللازمة التي تمكن هذا الأخير من أن يتبين على نحو مضبوط الطريقة التي أنجز بها الوكيل تلك المهمة.\nوإذا تسلم الموكل الإخطار، ثم تأخر في الرد أكثر مما تقتضيه طبيعة القضية أو العرف[263]، اعتبر أنه أقر ما فعله الوكيل، ولو كان هذا قد تجاوز حدود وكالته.",
  "908": "على الوكيل أن يقدم لموكله حسابا عن أداء مهمته، وأن يقدم له حسابا تفصيليا عن كل ما أنفقه وما قبضه، مؤيدا بالأدلة التي يقتضيها العرف[264] أو طبيعة التعامل وأن يؤدي له كل ما تسلمه نتيجة الوَكالة أو بمناسبتها.",
  "909": "الوكيل مسؤول عن الأشياء التي يتسلمها بمناسبة وكالته، وفقا لأحكام الفصول 791 و792 و804 و813.\nإلا أنه إذا كانت الوَكالة بأجر، فإن الوكيل يسأل، وفقا لما هو مذكور في الفصل 807.",
  "910": "يجب أن تفهم أحكام الفصل 908 السابق على نحو أكثر تسامحا إذا كان الوكيل ينوب عن زوجته أو أخته أو شخص آخر من عائلته.\nوفي هذه الحالات، يمكن، وفقا لظروف الحال، أن يصدق الوكيل بيمينه، فيما يتعلق برد الأشياء التي تسلمها لحساب موكله.",
  "911": "على الوكيل، بمجرد انتهاء الوَكالة، أن يرد رسم الوَكالة لموكله أو أن يودعه في المحكمة.\nالموكل أو خلفاؤه الذين لا يطلبون رد رسم الوَكالة يتحملون بالتعويضات تجاه الغير حسني النية.",
  "912": "إذا تعدد الوكلاء، فإن التضامن لا يقوم بينهم، إلا إذا اشترط. ومع ذلك فإن التضامن يقوم بقوة القانون بين الوكلاء:\nأولا - إذا حدث الضرر للموكل بتدليسهم أو بخطإهم المشترك، وتعذر تحديد نصيب كل منهم في وقوعه؛\nثانيا - إذا كانت الوَكالة غير قابلة للتجزئة؛\nثالثا - إذا أعطيت الوَكالة بين التجار لأعمال التجارة، ما لم يشترط غير ذلك.\nإلا أن الوكلاء، ولو كانوا متضامنين، لا يسألون عما يكون قد أجراه أحدهم خارج حدود الوَكالة، أو بإساءته مباشرتها.",
  "913": "على الموكل أن يمد الوكيل بالنقود وغيرها مما يلزم لتنفيذ الوَكالة، ما لم يقض العرف[265] أو الاتفاق بخلافه.",
  "914": "على الموكل:\nأولا - أن يدفع للوكيل ما اضطر إلى تسبيقه من ماله وإلى إنفاقه من المصروفات من أجل تنفيذ الوَكالة، في حدود ما كان لازما لهذا الغرض، وأن يدفع له أجره عندما يكون مستحقا، أيا ما كانت نتيجة المعاملة، ما لم يكن هناك فعل أو خطأ يعزى إليه؛\nثانيا - تخليص الوكيل من الالتزامات التي اضطر إلى التعاقد عليها نتيجة تنفيذه لمهمته أو بمناسبتها. وهو لا يسأل عن الالتزامات التي يتحمل بها الوكيل ولا عن الخسائر التي تلحقه نتيجة فعله أو خطإه أو من أجل أسباب أخرى بعيدة عن الوَكالة.",
  "915": "لا حق للوكيل في الأجر المتفق عليه:\nأولا - إذا منع، بقوة قاهرة، من مباشرة تنفيذ الوَكالة؛\nثانيا - إذا كانت الصفقة أو العملية التي كلف بها قد أنجزت قبل أن يشرع في تنفيذها؛\nثالثا - إذا لم تقع الصفقة أو القضية التي أعطيت الوَكالة من أجلها مع عدم الإخلال، في هذه الحالة، بما يقضي به عرف[266] التجارة أو العرف[267] المحلي.\nومع ذلك فللقاضي السلطة لتقدير ما إذا كان يجب، وفقا لظروف الحال، منح الوكيل تعويضا، لاسيما إذا لم تعقد الصفقة لسبب شخصي يتعلق بالموكل، أو بسبب القوة القاهرة.",
  "916": "إذا لم يكن الأجر قد عين، فإنه يعين وفقا لعرف المكان، الذي نفذت فيه الوَكالة وإلا فوفقا لظروف الحال.",
  "917": "الموكل الذي يحيل القضية لوكيل آخر، يبقى مسؤولا تجاه الوكيل الأول عن كل نتائج الوَكالة وفقا للفصل 914، ما لم يشترط اشتراط مخالف يقبله الوكيل الأول.",
  "918": "إذا أعطيت الوَكالة من عدة أشخاص لأجل قضية مشتركة بينهم، فإن كلا منهم يكون مسؤولا تجاه الوكيل بنسبة مصلحته في تلك القضية ما لم يتفق على غير ذلك.",
  "919": "للوكيل حق حَبْس أمتعة الموكل المنقولة أو بضائعه التي أرسلت إليه، من أجل استيفاء ما يستحق له على الموكل وفقا للفصل 914.",
  "920": "إذا أبرم الوكيل العقد باسمه الشخصي، كسب الحقوق الناشئة عنه، وظل ملتزما مباشرة تجاه من تعاقد معهم كما لو كانت الصفقة لحسابه ولو كان هؤلاء قد علموا بأنه معير اسمه أو أنه وكيل بالعمولة.",
  "921": "الوكيل الذي يتعاقد بصفته وكيلا وفي حدود وكالته لا يتحمل شخصيا بأي التزام تجاه من يتعاقد معهم. ولا يسوغ لهؤلاء الرجوع إلا على الموكل.",
  "922": "ليس للغير أي دعوى على الوكيل بوصفه هذا، من أجل إلزامه بتنفيذ الوَكالة ما لم تكن الوَكالة قد أعطيت له لمصلحتهم أيضا.",
  "923": "تثبت للغير على الوكيل دعوى من أجل إلزامه بقبول تنفيذ العقد، إذا كان هذا التنفيذ يدخل ضرورة في وكالته.",
  "924": "لمن يتعامل مع الوكيل، بصفته هذه، الحق دائما في أن يطالبه بإبراز رسم وكالته وله عند الحاجة أن يطلب منه نسخة مصدقة من هذا الرسم، وعندئذ تكون نفقة هذه النسخة عليه.",
  "925": "التصرفات التي يجريها الوكيل على وجه صحيح باسم الموكل وفي حدود وكالته تنتج آثارها في حق الموكل فيما له وعليه، كما لو كان هو الذي أجراها بنفسه.",
  "926": "يلتزم الموكل مباشرة بتنفيذ التعهدات المعقودة لحسابه من الوكيل في حدود وكالته.\nالتحفظات والعقود السرية المبرمة بين الموكل والوكيل والتي لا تظهر من الوَكالة نفسها لا يجوز الاحتجاج بها على الغير، ما لم يقم الدليل على أنهم كانوا يعلمون بها عند العقد.",
  "927": "لا يلتزم الموكل بما يجريه الوكيل خارج حدود وكالته أو متجاوزا إياها، إلا في الحالات الآتية:\nأولا: إذا أقره، ولو دلالة؛\nثانيا: إذا استفاد منه؛\nثالثا: إذا أبرم الوكيل التصرف بشروط أفضل مما تضمنته تعليمات الموكل؛\nرابعا: وحتى إذا أبرم الوكيل التصرف بشروط أقسى مما تضمنته تعليمات الموكل مادام الفرق يسيرا، أو كان مما يتسامح به في التجارة أو في مكان إبرام العقد.",
  "928": "إذا تصرف الوكيل بلا وكالة، أو تجاوز حدود وكالته، وتعذر لذلك تنفيذ العقد الذي أبرمه، التزم بالتعويضات لمن تعاقد معه.\nولكن الوكيل لا يتحمل بأي ضمان:\nأ - إذا أعلم من تعاقد معه بمضمون وكالته علما كافيا؛\nب - إذا أثبت أن من تعاقد معه كان يعلم بمضمون وكالته.\nوكل ذلك، ما لم يلتزم الوكيل بأن يجعل الموكل يقوم بتنفيذ العقد[268].",
  "929": "تنتهي الوَكالة:\nأولا - بتنفيذ العملية التي أعطيت من أجلها؛\nثانيا - بوقوع الشرط الفاسخ الذي علقت عليه، أو بفوات الأجل الذي منحت لغايته؛\nثالثا - بعزل الوكيل؛\nرابعا - بتنازل الوكيل عن الوَكالة؛\nخامسا - بموت الموكل أو الوكيل؛\nسادسا - بحدوث تغيير في حالة الموكل أو الوكيل من شأنه أن يفقده أهلية مباشرة حقوقه، كما هي الحال في الحَجْر والإفلاس[269]. وذلك ما لم ترد الوَكالة على أمور يمكن للوكيل تنفيذها، برغم حدوث هذا التغيير في الحالة؛\nسابعا - باستحالة تنفيذ الوَكالة لسبب خارج عن إرادة المتعاقدين.",
  "930": "الوَكالة المعطاة من شخص معنوي أو من شركة تنتهي بانتهاء ذاك الشخص أو هذه الشركة[270].",
  "931": "للموكل أن يلغي الوَكالة متى شاء. وكل شرط يخالف ذلك يكون عديم الأثر، بالنسبة إلى المتعاقدين وإلى الغير على حد سواء، ولا يمنع اشتراط الأجر من مباشرة الحق.\nإلا أنه:\nأولا - إذا كانت الوَكالة قد أعطيت في مصلحة الوكيل أو في مصلحة الغير، لم يسغ للموكل أن يلغيها إلا بموافقة من أعطيت في مصلحته؛\nثانيا - لا يسوغ عزل وكيل الخصومة متى أصبحت الدعوى جاهزة للحكم.",
  "932": "يصح أن يكون إلغاء الوَكالة صريحا أو ضمنيا.\nوإذا تم إلغاء الوَكالة بمكتوب أو ببرقية، فإنه لا ينتج أثره إلا من وقت تسلم الوكيل المكتوب أو البرقية.",
  "933": "إذا أعطيت الوَكالة من عدة أشخاص من أجل نفس الصفقة، لم يسغ إلغاؤها إلا بموافقتهم جميعا. غير أنه إذا كانت هذه الصفقة قابلة للتجزئة، فإن الإلغاء الحاصل من أحد الموكلين ينهي الوَكالة بالنسبة إلى نصيبه منها.\nيجوز، في شركات التضامن وغيرها من الشركات، إلغاء الوَكالة من أي واحد من الشركاء الذين لهم صلاحية إعطائها باسم الشركة.",
  "934": "إلغاء الوَكالة كليا أو جزئيا لا يحتج به في مواجهة الغير الذين تعاقدوا بحسن نية مع الوكيل، قبل علمهم بحصوله. وللموكل أن يرجع على الوكيل.\nإذا تطلب القانون شكلا خاصا لإنشاء الوَكالة، وجبت مراعاة نفس هذا الشكل في إلغائها.",
  "935": "لا يحق للوكيل التنازل عن الوَكالة إلا إذا أخطر به الموكل. وهو مسؤول عن الضرر الذي يرتبه هذا التنازل للموكل، إذا لم يتخذ الإجراءات اللازمة للمحافظة على مصالحه محافظة تامة إلى أن يتمكن من رعايتها بنفسه.",
  "936": "لا يحق للوكيل التنازل عن الوَكالة إذا كانت قد أعطيت له في مصلحة الغير، إلا لمرض أو عذر آخر مقبول. وفي هذه الحالة يجب عليه أن يخطر الغير الذي أعطيت الوَكالة في مصلحته بتنازله، وأن يمنحه أجلا معقولا ليتدبر خلاله أمره، على نحو ما تقتضيه ظروف الحال.",
  "937": "عزل الوكيل الأصلي أو موته يؤدي إلى عزل من أحله محله. ولا يسري هذا الحكم:\nأولا: إذا كان نائب الوكيل قد عين بإذن الموكل؛\nثانيا: إذا كان للوكيل الأصلي صلاحيات تامة في التصرف، أو إذا كان له الإذن في أن يحل غيره محله.",
  "938": "موت الموكل أو حدوث تغيير في حالته ينهي وكالة الوكيل الأصلي ووكالة نائبه. ولا يسري هذا الحكم:\nأولا: إذا كانت الوَكالة قد أعطيت في مصلحة الوكيل أو في مصلحة الغير؛\nثانيا: إذا كان محلها إجراء عمل بعد وفاة الموكل، على نحو يكون الوكيل معه في مركز منفذ الوصايا.",
  "939": "تكون صحيحة التصرفات التي يبرمها الوكيل باسم الموكل خلال الفترة التي يجهل فيها موته أو غيره من الأسباب التي يترتب عليها انقضاء الوَكالة بشرط أن يكون من تعاقد معه يجهل ذلك بدوره.",
  "940": "إذا انقضت الوَكالة بوفاة الموكل أو بإفلاسه[271] أو بنقص أهليته، وجب على الوكيل عندما يكون في التأخير خطر، أن يتم العمل الذي بدأه، في حدود ما هو ضروري. كما أنه يجب عليه أن يتخذ كل ما تقتضيه الظروف من إجراءات لصيانة مصلحة الموكل، إذا لم يكن لهذا الأخير وارث متمتع بالأهلية، أو لم يوجد له أو لوارثه نائب قانوني. ومن ناحية أخرى يكون للوكيل الحق في استرداد ما سبقه وما أنفقه من مصروفات لتنفيذ الوَكالة، وفقا لأحكام الفضالة.",
  "941": "في حالة موت الوكيل، يجب على ورثته، إن كانوا على علم بالوَكالة أن يبادروا بإعلام الموكل به. كما أنه يجب عليهم أن يحافظوا على الوثائق وغيرها من المستندات التي تخص الموكل.\nولا يسري هذا الحكم على الورثة، إن كانوا قاصرين، طالما لم يعين لهم وصي.",
  "942": "إذا فسخ الموكل أو الوكيل العقد بغتة، وفي وقت غير لائق ومن غير سبب معتبر، ساغ الحكم لأحدهما على الآخر بالتعويض عما لحقه من ضرر، ما لم يتفق على غير ذلك.\nوالقاضي هو الذي يحدد التعويض في وجوده ومداه، وفقا لطبيعة الوَكالة وظروف التعامل وعرف[272] المكان.",
  "943": "إذا باشر شخص، باختياره أو بحكم الضرورة، شؤون أحد من الغير، في غيابه أو بدون علمه، وبدون أن يرخص له في ذلك منه أو من القاضي، قامت هناك علاقة قانونية مماثلة للعلاقة الناشئة عن الوَكالة وخضعت للأحكام الآتية:",
  "944": "على الفُضولي أن يمضي في العمل الذي بدأه إلى أن يتمكن رب العمل من الاستمرار فيه بنفسه، إذا كان من شأن انقطاع العمل أن يضر برب العمل.",
  "945": "على الفُضولي أن يبذل في مباشرته العمل، عناية الحازم الضابط لشؤون نفسه، وأن يسير فيه على مقتضى رغبة رب العمل المعروفة منه أو المفترضة، وهو مسؤول عن كل خطإ يقع منه، ولو كان يسيرا. أما إذا كان تدخله بقصد دفع ضرر حال وكبير كان يهدد رب العمل، أو بقصد إتمام واجبات وكالة كانت لموروثه فإنه لا يسأل إلا عن تدليسه أو خطإه الفاحش.",
  "946": "يتحمل الفُضولي بنفس الالتزامات التي يتحمل بها الوكيل بالنسبة إلى تقديم الحسابات ورد كل ما يتسلمه نتيجة مباشرة العمل.\nوهو يتحمل بكل الالتزامات الأخرى الناشئة من الوَكالة الصريحة.",
  "947": "الفُضولي الذي يتدخل في شؤون غيره، خلافا لرغبته المعروفة أو المفترضة أو الذي يجري عمليات تخالف رغبته المفترضة، يسأل عن كل ما يلحق رب العمل من ضرر نتيجة فعله ولو لم يكن هناك خطأ يمكن أن يعزى إليه.",
  "948": "غير أنه لا يجوز الاحتجاج بمخالفة رغبة رب العمل، إذا اضطر الفُضولي لأن يعمل على وجه السرعة ما يقتضيه:\nأولا - الوفاء بالتزام يتحمل به رب العمل ويتطلب الصالح العام تنفيذه؛\nثانيا - الوفاء بالتزام قانوني بالنفقة أو بالمصروفات الجنائزية أو بالتزامات أخرى من نفس طبيعتها.",
  "949": "إذا باشر الفُضولي العمل في مصلحة صاحبه وعلى وجه ينفعه، كسب هذا الأخير كل الحقوق وتحمل مباشرة بكل الالتزامات التي تعاقد الفُضولي عليها لحسابه ويجب عليه أن يبرئ الفُضولي من كل العواقب المترتبة على مباشرته العمل، وأن يعوضه عن المبالغ التي سبقها وعن المصروفات التي أنفقها والخسائر التي تحملها، وفقا لأحكام الفصل 914.\nوتعتبر مباشرة العمل حسنة، أيا ما كانت نتيجته، إذا كان عند إجرائه، مطابقا لقواعد الإدارة الحسنة، وفقا لما تقتضيه ظروف الحال.",
  "950": "إذا كان العمل مشتركا بين عدة أشخاص، التزم هؤلاء تجاه الفُضولي بنسبة مصلحة كل منهم فيه، وفقا لأحكام الفصل السابق.",
  "951": "للفُضولي حق حَبْس الأشياء المملوكة لرب العمل، من أجل ضمان المبالغ التي يمنحه الفصل 949 حق استردادها.\nوليس له ذلك إذا تدخل في أمر صاحب الحق كرها عليه.",
  "952": "في جميع الحالات التي لا يلتزم فيها رب العمل بأن يدفع للفُضولي ما أنفقه من المصروفات، يسوغ لهذا الأخير أن يزيل ما أجراه من التحسينات، بشرط أن يمكنه ذلك من غير ضرر، أو أن يطلب من رب العمل تسليمه الأشياء التي اشتراها له إذا لم يقبلها.",
  "953": "من أسس الفضالة أن تكون بغير أجر.",
  "954": "لا يلتزم رب العمل بدفع أي مبلغ، إذا كان الفُضولي قد باشر العمل بدون قصد استرداد ما يسبقه. وهذا القصد يفترض:\nأ - إذا كان العمل قد أجري برغم إرادة صاحب الحق، مع استثناء الحالة المنصوص عليها في الفصل 948؛\nب - في جميع الأحوال التي يظهر فيها بوضوح من الظروف أنه لم يكن لدى الفُضولي قصد استرداد تسبيقاته.",
  "955": "إذا غلط الفُضولي في شخصية رب العمل، فإن الحقوق والالتزامات الناشئة من مباشرة العمل تقوم بينه وبين رب العمل الحقيقي.",
  "956": "إذا تصرف شخص في أمر ظنا منه أنه له، فتبين أنه لغيره فإن العلاقات التي تقوم بينه وبين ذلك الغير تخضع للأحكام المتعلقة بالإثراء بلا سبب.",
  "957": "موت الفُضولي ينهي الفضالة، وتخضع التزامات ورثته لأحكام الفصل 941.",
  "958": "إذا أقر رب العمل صراحة أو دلالة، ما فعله الفُضولي، فإن الحقوق والالتزامات الناشئة بين الطرفين تخضع لأحكام الوَكالة ابتداء من مباشرة العمل. أما في مواجهة الغير، فلا يكون للإقرار أثر إلا ابتداء من وقت حصوله.",
  "745 مكرر": "(ظهير 8 أبريل 1938)\nلكل من يقدم خدماته بمقتضى عقد أن يطلب عند انقضائه من رب العمل، شهادة لا تتضمن إلا تاريخ التحاقه بالخدمة وتاريخ تركه إياها وتقديره المهني خلال الستة الأشهر الأخيرة السابقة لانقضاء العقد. فإن لم تقدم له هذه الشهادة، حق له التعويض.\nتعفى شهادات العمل المعطاة للعمال والمستخدمين والخدم من التمبر والتسجيل، ولو اشتملت على بيانات أخرى غير تلك المذكورة في الفقرة السابقة مادامت هذه البيانات لا تتضمن التزاما ولا توصيلا ولا أي اتفاق آخر مما يخضع للتمبر أو للتسجيل.\nويشمل الإعفاء الرسم الذي يتضمن عبارة \"حر من كل التزام\" أو أي صياغة أخرى تثبت انقضاء عقد العمل انقضاء طبيعيا والصفات المهنية والخدمات المؤداة[210].",
  "745 مكرر مرتين": "(ظهير 6 يوليوز 1954) التوصيل الذي يعطيه العامل لرب العمل، عند فسخ أو انقضاء عقده، بتصفية كل حساباته تجاهه، يجوز نقضه خلال الثلاثين يوما التالية لتوقيعه.\nيبطل كل ما يصدر من الأجير في التوصيل من تنازل عن المكافآت الممنوحة عن العطل السنوية المدفوعة وعن المكافآت المستحقة له تعويضا عن العطل التي لم يأخذها، وعن المكافآت والمزايا المقررة بمقتضى العقد الجماعي والتي مازالت مستحقة له، وعن التعويضات التي قد تستحق له نتيجة إنهاء العقد بمقتضى الفصل 754 التالي:\nيلزم أن يتضمن التوصيل البيانات الآتية، وإلا وقع باطلا:\nأ - جملة المبلغ المدفوع للأجير تصفية لكل حساباته مكتوبا بخط يده. كما يلزم على الأجير أن يكتب قبل توقيعه عبارة \" قرئ وصودق عليه \". وإذا كان الأجير أميا، استبدل بتوقيعه توقيع شاهدين يختارهما بنفسه؛\nب - ميعاد السقوط المذكور في الفقرة الأولى مكتوبا بحروف تقرأ بوضوح؛\nج - أنه حرر في نظيرين أعطي أحدهما للأجير.\nويلزم إجراء نقض التوصيل إما بخطاب مضمون موجه لرب العمل، وإما برفع الدعوى أمام محكمة الشغل وعند عدم اختصاصها، أمام محكمة السدد[211] وهو لا يصلح إلا بشرط توضيح الحقوق المختلفة التي يدعيها الأجير لنفسه.\nالتوصيل عن صافي كل الحسابات الذي يحصل نقضه على وجه قانوني أو ذلك الذي لم يفت بعد ميعاد نقضه، لا يكون له إلا قيمة التوصيل البسيط بالمبالغ المذكورة فيه[212].",
  "745 مكرر ثلاث مرات": "(ظهير 6 يوليوز 1954) القبول الصادر من الأجير، بدون احتجاج أو تحفظ، لوثيقة الدفع أو لأي محرر آخر يتضمن الوفاء بالأجر، لا يعتبر تنازلا منه عن حقه في الأجر المستحق له كله أو بعضه، ولا عن المكافآت وتوابع الأجر المستحقة له بمقتضى الأحكام التشريعية أو التنظيمية أو التعاقدية أو بمقتضى أحكام الاتفاقات الجماعية. ويسري هذا الحكم ولو كان الأجير قد ذكر في ذيل المحررة عبارة \"قرئ وصودق عليه\" متبوعة بإمضائه[213].\nوكذلك لا يعتبر القبول السابق بمثابة إنهاء الحساب وتصفيته في معنى الفصل 382 من هذا الظهير والفصل 282[214] من ظهير 12 غشت 1913 (9 رمضان 1331) المكون لقانون المسطرة المدنية.",
  "758 مكرر": "(ظهير 6 يوليوز 1954) إذا جاء الأجير بعد أن قطع عقد العمل على نحو تعسفي، فأجر مرة أخرى خدماته فإن رب العمل الجديد يسأل بالتضامن عن الضرر الحادث لرب العمل القديم:\nأولا - إذا ثبت تدخله في قطع الأجير عمله الأول؛\nثانيا - إذا شغل عاملا وهو يعلم بسبق ارتباطه بعقد عمل؛\nثالثا - أو إذا استمر في تشغيل عامل بعد علمه بسبق ارتباطه، بمقتضى عقد عمل، برب عمل آخر.\nوفي هذه الحالة الأخيرة تنتهي مسؤولية رب العمل الجديد إذا حدث في الوقت الذي أخطر فيه بسبق ارتباط العامل، إن كان عقد العمل الذي قطع تعسفيا من الأجير قد انقضى بفوات أجله متى كان قد عقد لمدة محددة، أو إذا كان ميعاد التنبيه قد انقضى أو كانت قد فاتت مدة خمسة عشر يوما من قطع العقد، متى كان عقد العمل غير محدد المدة[243]."
};
